 }

+void NetworkStatus::openNetworkLoginPage(const QString &startupId)
+{
+    const KService::Ptr service = KService::serviceByDesktopName(QStringLiteral("org.kde.plasma.networkmanagement.captiveportal"));
+    if (service) {
+        auto job = new KIO::ApplicationLauncherJob(service);
+        job->setUrls({networkCheckUrl()});
+        job->setStartupId(startupId.toUtf8());
+        job->start();
+    } else {
+        auto job = new KIO::OpenUrlJob(networkCheckUrl());
+        job->setStartupId(startupId.toUtf8());
+        job->start();
+    }
+}
