@@ -0,0 +1,75 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: GPL-2.0-only OR GPL-3.0-only OR LicenseRef-KDE-Accepted-GPL
+*/
+
+#include <QApplication>
+#include <QCommandLineParser>
+#include <QIcon>
+#include <QWebEngineNewWindowRequest>
+#include <QWebEnginePage>
+#include <QWebEngineProfile>
+#include <QWebEngineView>
+
+#include <functional>
+
+#include <KLocalizedString>
+
+#include <NetworkManagerQt/Manager>
+
+int main(int argc, char **argv)
+{
+    QApplication app(argc, argv);
+    KLocalizedString::setApplicationDomain("plasmanetworkmanagement-captiveportal");
+    app.setApplicationName(QStringLiteral("plasma-nm-captive-portal"));
+    app.setApplicationDisplayName(i18nc("@title:window", "Network Login"));
+    app.setDesktopFileName(QStringLiteral("org.kde.plasma.networkmanagement.captiveportal"));
+    app.setWindowIcon(QIcon::fromTheme(QStringLiteral("preferences-system-network")));
+
+    QCommandLineParser parser;
+    parser.addPositionalArgument(QStringLiteral("url"), i18n("Login page of the network"));
+    parser.process(app);
+
+    QUrl url = parser.positionalArguments().isEmpty() ? QUrl() : QUrl::fromUserInput(parser.positionalArguments().constFirst());
+    if (url.isEmpty()) {
+        url = QUrl(NetworkManager::connectivityCheckUri());
+    }
+
+    // Off the record: nothing the portal sets is kept after the window is closed
+    QWebEngineProfile profile;
+
+    // Terms or login forms that the portal opens in a new window get their own window, so the login page stays
+    std::function<QWebEngineView *()> createView = [&profile, &createView]() {
+        auto view = new QWebEngineView;
+        view->setAttribute(Qt::WA_DeleteOnClose);
+        view->setPage(new QWebEnginePage(&profile, view));
+        QObject::connect(view->page(), &QWebEnginePage::newWindowRequested, view, [&createView](QWebEngineNewWindowRequest &request) {
+            QWebEngineView *newView = createView();
+            request.openIn(newView->page());
+            newView->show();
+        });
+        QObject::connect(view->page(), &QWebEnginePage::windowCloseRequested, view, &QWidget::close);
+        QObject::connect(view, &QWebEngineView::titleChanged, view, &QWidget::setWindowTitle);
+        QObject::connect(view, &QWebEngineView::loadFinished, view, [] {
+            NetworkManager::checkConnectivity();
+        });
+        view->resize(800, 600);
+        return view;
+    };
+
+    QObject::connect(NetworkManager::notifier(), &NetworkManager::Notifier::connectivityChanged, &app, [](NetworkManager::Connectivity connectivity) {
+        if (connectivity == NetworkManager::Full) {
+            QApplication::closeAllWindows();
+        }
+    });
+
+    QWebEngineView *view = createView();
+    view->setUrl(url);
+    view->show();
+
+    const int ret = app.exec();
+    // Pages must go before their profile
+    qDeleteAll(QApplication::topLevelWidgets());
+    return ret;
+}
